/* music.h - the dynamic music engine's public API (owner: MU0; maintainer
 * MU1, add-only; docs/design/music/SPEC.md sec.9.1 + the critique fixes).
 *
 * Cues (MC_*), stingers (STG_*), vinyl patterns (VINYL_*) and motifs are
 * ids generated by tools/mmlc.py into core/gen/mus_ids.h from the locks in
 * core/music/ids/. The engine ticks inside audio_tick() (music_update(),
 * D12); the 240 Hz driver (mus_drv_tick) runs in the platform's IRQ, or
 * inside music_update() on the weak legacy bridge (platform.h sec.9.4).
 *
 * Compatibility: the classic audio_music*() calls (audio.h) keep working
 * and route here (audio_seq.c). Integer only. */
#ifndef DOOMO_MUSIC_H
#define DOOMO_MUSIC_H

#include "types.h"
#include "mus_data.h"
#include "../../gen/mus_ids.h"

/* grids */
enum { MQ_NOW, MQ_16TH, MQ_BEAT, MQ_BAR, MQ_PHRASE, MQ_NODE_END, MQ_MARKER, MQ_COUNT };

/* ---- cues ---------------------------------------------------------------- */
void music_set_cue(int cue, int grid);                       /* via the matrix; no-op if playing/armed */
typedef struct MusCueReq { uint8_t cue, grid, type, arg, entry, max_wait, flags, pad; } MusCueReq;
void music_set_cue_ex(const MusCueReq *r);
void music_set_cue_dual(int cue_a, int cue_b);
int  music_cue(void);
void music_resume(int cue);

/* ---- params: 0..255 targets, smoothed ------------------------------------- */
enum { MP_INTENSITY, MP_DANGER, MP_ENEMIES, MP_HP, MP_COMBO, MP_BOSS_PHASE, MP_HELL, MP_INFECT, MP_HOUR,
       MP_WEATHER, MP_SEASON, MP_CROWD, MP_ACTIVITY, MP_WALL_DIST, MP_ZONE, MP_SANITY, MP_COMFORT, MP_SPOOK,
       MP_FORT, MP_PET_STAGE, MP_PET_LINE, MP_TENSION, MP_HEAT, MP_TIMER, MP_HYPE, MP_TRUST, MP_LOVE,
       MP_ALTITUDE, MP_DIALOG, MP_MENU, MP_HARMONY /* house Style, Ch4 */, MP_QUEST /* family */, MP_COUNT /* 32 */ };
void music_set_param(int p, int v);
void music_set_param_now(int p, int v);
int  music_param(int p);
void music_pulse_duck(int gain_q8, int ticks);
int  music_intensity(void);

/* ---- stingers, quotes, vinyl ----------------------------------------------- */
enum { STF_OVER, STF_REPLACE, STF_NO_DUCK = 2 };
int  music_sting(int sting, int grid, int flags);            /* -> ticks until the hit is audible; -1 refused */
int  music_sting_at(int sting, uint32_t land_tick, int flags);
void music_quote(int motif, int prio);
enum { VSRC_AUTO, VSRC_DECK, VSRC_TAPE, VSRC_HYBRID };
enum { AFTER_DEFAULT, AFTER_RESUME, AFTER_CONTINUE, AFTER_STOP, AFTER_NEXT_CUE };
int  music_vinyl(int pattern, int grid, int source, int after);   /* -> ticks until it lands; -1 refused */
int  music_vinyl_at(int pattern, uint32_t land_tick, int source, int after);
void music_vinyl_live(int16_t speed_q8, uint8_t fader);      /* DJ booth; 0x7FFF releases */
void music_resume_on_beat(void);
void music_sfx_synth(int sfx);

/* ---- timing and the comic bridge -------------------------------------------- */
typedef struct MusPos {
    uint32_t mt;                                             /* audible driver time      */
    uint16_t bar;
    uint8_t  beat, sub48, cue, node, pass, beats_per_bar;
    uint16_t bpm_q4;
    uint8_t  key, chord_root;
    uint16_t chord_pcs, pad;
} MusPos;                                                    /* 20 B, audible */
void music_pos(MusPos *out);
int  music_ticks_to(int grid);
int  music_land(int grid, int frames, int max_bend_q8);      /* <= +-12 %; returns the residual */
enum { MB_BEAT = 1, MB_BAR = 2, MB_PHRASE = 4, MB_NODE = 8, MB_MARKER = 16, MB_STING_HIT = 32,
       MB_VINYL_END = 64, MB_CUE = 128 };
typedef struct MusBeatEv {
    uint8_t  kind, node;
    uint16_t bar;
    uint8_t  beat, marker;
    int8_t   due;
    uint8_t  cue, key, chord_root;
    uint16_t chord_pcs;
} MusBeatEv;                                                 /* 12 B */
typedef void (*MusBeatFn)(const MusBeatEv *ev);
int  music_on_beat(MusBeatFn fn, uint8_t mask);              /* RESIDENT callers only (SS C6) */
void music_off_beat(int slot);
int  music_beat_events(MusBeatEv *out, int max);             /* scenes poll */
void music_mute_window(int from, int to);                    /* ticks from now */
void music_duck_window(int from, int to, int gain_q8);
int  music_gated(void);                                      /* scripted silence only (CF-25) */
int  music_resting(void);                                    /* the engine's own rests (CF-25) */
uint16_t music_snap_pitch(uint16_t pitch16);                 /* babble in tune */

/* ---- system ------------------------------------------------------------------- */
enum { STALL_NONE, STALL_LOAD, STALL_SAVE, STALL_CARD };
void music_stall(int kind);
void music_prefill(int ms);
enum { AP_3D, AP_OVERWORLD, AP_UI, AP_CUTSCENE, AP_MUSIC, AP_HOUSE, AP_UI_EDGE /* CF-6 */ };
void music_profile(int scene_class);
void music_update(void);                                     /* audio_tick() calls it (D12) */
uint32_t music_hash(int cue, int minutes);                   /* T2: hash mode (CF-33)       */

/* ---- MU1 additions (add-only) -------------------------------------------------- */
/* The cue a classic SONG_* resolves to (CF-29; M1: its classic cue). */
int  mus_bind_cue(int song, int scene, int map, int arg);
/* 1 if `cue` exists in the bank. */
int  music_cue_exists(int cue);
/* Ticks (30 Hz) of one pass of a cue (classic: the whole song; adaptive:
 * the current node), 0 if unknown (CF-22). */
uint32_t music_cue_length(int cue);
/* Display name of a cue ("" if none). */
const char *music_cue_name(int cue);
/* M4: music_update() calls so far - the clock of music_sting_at() and
 * music_vinyl_at() (an event lands on tick T when it is dispatched in the
 * update that brings music_now() to T). */
uint32_t music_now(void);
/* M4: ambient beds (sec.6.5), seeded emitters that play while the music
 * rests or is silent ([NO MUSIC]); the scene says which (a mask of 1 << MBED_*),
 * hour gates the birds and the crickets. 0 = none (the default). */
enum { MBED_BIRDS, MBED_CRICKETS, MBED_WIND, MBED_RAIN, MBED_RIVER, MBED_LAVA, MBED_VAPE, MBED_CROWD,
       MBED_CLOCK, MBED_MACHINERY, MBED_EMBERS, MBED_FIREWORKS, MUS_BED_COUNT };
void music_beds(uint16_t mask);

#endif
